-- Original grade-eight writing support; preserve imported titles and source caveat.
WITH qa(n,skill,passage,prompt,correct,w1,w2,w3,practice) AS (VALUES (20,'وصف المكان: تخطيط','اختارت ليان السوق مكانًا لقصتها، فسجلت الممرات والروائح وأصوات الباعة قبل أن تكتب حوار البطلة. انتقت التفاصيل التي تساعد القارئ على تصور مكان الحدث.','أي عنصر حسي يناسب وصف السوق؟','أصوات الباعة','اسم معلم الرياضيات','رقم سري مجهول','موعد الرحلة في بلد آخر','خطط لقصة قصيرة داخل سوق أو مكتبة مع ثلاثة تفاصيل حسية وحدث يرتبط بالمكان.'),
(21,'وصف المكان: سرد','دخل بدر متحفًا صغيرًا مع زملائه، فلاحظ الإضاءة الهادئة والممر المؤدي إلى ركن الأدوات القديمة. دفعه منظر قطعة إلى سؤال المرشد عنها، فأصبح وصف المكان جزءًا من الحدث.','ما الذي ربط الوصف بالحدث في المتحف؟','سؤال بدر عن قطعة شاهدها','تكرار اللون وحده','غياب كل الشخصيات','الحذف التام لوصف المكان','اكتب مشهدًا من ست جمل في مكان ثقافي يجمع وصفًا محسوسًا وفعلًا من الشخصية.'),
(22,'وصف المكان: تحرير','كرر الكاتب عبارة «كانت الحديقة جميلة» ثلاث مرات. اقترحت معلمته بدائل دقيقة مثل ظل الأشجار على المقاعد وصوت المياه القريب وامتداد الممر؛ فصار الوصف أكثر وضوحًا.','أي بديل يحسن الوصف العام المكرر؟','ظل الأشجار على المقاعد','المكان جميل جدًا جدًا','إنه جيد دون تفصيل','إلغاء المكان من القصة','استبدل ثلاث صفات عامة في فقرة بتفاصيل بصرية وصوتية تؤثر في السرد.'),
(23,'تلخيص قصة: الفكرة','لاحظت ريم كتبًا تالفة في المكتبة الصفية، فدعت زميلاتها إلى إصلاح أغلفتها بإشراف المعلمة. رتب الفريق الكتب بعد العمل؛ فأظهر ملخص القصة المشكلة والتعاون والنتيجة.','ما الفكرة الرئيسة للقصة؟','التعاون على إصلاح كتب الصف','الذهاب إلى الملعب','شراء ألعاب جديدة','وصف لون الستائر','لخص قصة ترميم الكتب في ثلاث جمل تتناول المشكلة والعمل الجماعي والنتيجة.'),
(24,'تلخيص قصة: تقويم','كتب أحمد ملخصًا طويلاً لقصة مساعدة جار مسن؛ ثم حذف التفاصيل غير اللازمة وأبقى سبب المساعدة والفعل والنتيجة. راجع المعلم أن النص الجديد من كلمات الطالب ويحفظ المعنى الأصلي.','ما معيار جودة الملخص؟','حفظ الفكرة الأساسية باختصار دون نسخ كامل','إضافة أحداث لم تقع','ذكر ألوان الأشياء دون حدث','حذف نتيجة القصة كلها','لخص قصة قصيرة في خمس جمل ثم اختصرها إلى ثلاث مع الحفاظ على المشكلة والحل.'))
UPDATE public.lessons l SET content=
'ضاديوم — تمرين كتابة أصلي للصف الثامن الفصل الأول. العنوان المستورد يحتاج مراجعة المصدر؛ النص التالي ليس نص الكتاب الرسمي.'||E'\n\n'||
'المهارة: '||qa.skill||E'\n\n'||'المثال الأصلي: '||qa.passage||E'\n\n'||'سؤال التحليل: '||qa.prompt||E'\n\n'||
'أطبق مهاريًا: '||qa.practice||E'\n\n'||
'هدف التعلم: تمييز الدليل في النص وكتابته بجملة ثم إنتاج وصف أو تلخيص مستقل ذي معنى.'||E'\n\n'||
'أسلوب التعلم: نشاط ثنائي لاستخراج الفكرة، ثم كتابة فردية، ثم تبادل التغذية الراجعة حول الصياغة والترابط.'||E'\n\n'||
'التمايز: يحدد المبتدئ كلمة دالة، ويكتب المتوسط فقرة قصيرة، ويحرر المتقدم فقرة مع تبرير تحسيناتها.'||E'\n\n'||
'تقويم بشري مطلوب: لا تُعد مهمة الكتابة مصححة آليًا بمجرد الإكمال.'||E'\n\n'||'الوصف القديم: '||l.content,updated_at=now()
FROM qa JOIN public.units u ON u.title='التعبير والكتابة' AND u.semester=1
JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=8
JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
WHERE l.unit_id=u.id AND l.sort_order=qa.n AND l.status='published'
AND l.content LIKE 'يتناول هذا الدرس موضوع%' AND length(l.content)<350;
WITH qa(n,skill,passage,prompt,correct,w1,w2,w3,practice) AS (VALUES (20,'وصف المكان: تخطيط','اختارت ليان السوق مكانًا لقصتها، فسجلت الممرات والروائح وأصوات الباعة قبل أن تكتب حوار البطلة. انتقت التفاصيل التي تساعد القارئ على تصور مكان الحدث.','أي عنصر حسي يناسب وصف السوق؟','أصوات الباعة','اسم معلم الرياضيات','رقم سري مجهول','موعد الرحلة في بلد آخر','خطط لقصة قصيرة داخل سوق أو مكتبة مع ثلاثة تفاصيل حسية وحدث يرتبط بالمكان.'),
(21,'وصف المكان: سرد','دخل بدر متحفًا صغيرًا مع زملائه، فلاحظ الإضاءة الهادئة والممر المؤدي إلى ركن الأدوات القديمة. دفعه منظر قطعة إلى سؤال المرشد عنها، فأصبح وصف المكان جزءًا من الحدث.','ما الذي ربط الوصف بالحدث في المتحف؟','سؤال بدر عن قطعة شاهدها','تكرار اللون وحده','غياب كل الشخصيات','الحذف التام لوصف المكان','اكتب مشهدًا من ست جمل في مكان ثقافي يجمع وصفًا محسوسًا وفعلًا من الشخصية.'),
(22,'وصف المكان: تحرير','كرر الكاتب عبارة «كانت الحديقة جميلة» ثلاث مرات. اقترحت معلمته بدائل دقيقة مثل ظل الأشجار على المقاعد وصوت المياه القريب وامتداد الممر؛ فصار الوصف أكثر وضوحًا.','أي بديل يحسن الوصف العام المكرر؟','ظل الأشجار على المقاعد','المكان جميل جدًا جدًا','إنه جيد دون تفصيل','إلغاء المكان من القصة','استبدل ثلاث صفات عامة في فقرة بتفاصيل بصرية وصوتية تؤثر في السرد.'),
(23,'تلخيص قصة: الفكرة','لاحظت ريم كتبًا تالفة في المكتبة الصفية، فدعت زميلاتها إلى إصلاح أغلفتها بإشراف المعلمة. رتب الفريق الكتب بعد العمل؛ فأظهر ملخص القصة المشكلة والتعاون والنتيجة.','ما الفكرة الرئيسة للقصة؟','التعاون على إصلاح كتب الصف','الذهاب إلى الملعب','شراء ألعاب جديدة','وصف لون الستائر','لخص قصة ترميم الكتب في ثلاث جمل تتناول المشكلة والعمل الجماعي والنتيجة.'),
(24,'تلخيص قصة: تقويم','كتب أحمد ملخصًا طويلاً لقصة مساعدة جار مسن؛ ثم حذف التفاصيل غير اللازمة وأبقى سبب المساعدة والفعل والنتيجة. راجع المعلم أن النص الجديد من كلمات الطالب ويحفظ المعنى الأصلي.','ما معيار جودة الملخص؟','حفظ الفكرة الأساسية باختصار دون نسخ كامل','إضافة أحداث لم تقع','ذكر ألوان الأشياء دون حدث','حذف نتيجة القصة كلها','لخص قصة قصيرة في خمس جمل ثم اختصرها إلى ثلاث مع الحفاظ على المشكلة والحل.')), s AS(
SELECT l.id,qa.* FROM qa JOIN public.lessons l ON l.sort_order=qa.n AND l.status='published'
JOIN public.units u ON u.id=l.unit_id AND u.title='التعبير والكتابة' AND u.semester=1
JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=8
JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
WHERE l.content LIKE 'ضاديوم — تمرين كتابة أصلي%' OR (l.content LIKE 'يتناول هذا الدرس موضوع%' AND length(l.content)<350))
INSERT INTO public.lesson_activities(lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
SELECT s.id,'فهم المثال الأصلي','multiple_choice','assessment',s.prompt,
jsonb_build_object('origin','DADYOOM_BH_G8_T1_WRITING_COMPLETION_LAST5_20261008','requiresOCRTitleReview',true,'notOfficialBook',true,'options',jsonb_build_array(s.correct,s.w1,s.w2,s.w3)),
jsonb_build_object('correct',s.correct),1,5,true,true FROM s WHERE NOT EXISTS(
SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=s.id AND a.content->>'origin'='DADYOOM_BH_G8_T1_WRITING_COMPLETION_LAST5_20261008' AND a.activity_type='multiple_choice');
