INSERT INTO public.lesson_activities(lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
SELECT s.id,'مهمة كتابة تحتاج مراجعة المعلم','writing','practice',s.practice,
jsonb_build_object('origin','DADYOOM_BH_G8_T1_WRITING_COMPLETION_LAST5_20261008','humanReviewRequired',true,'skillQualityAutoVerified',false,'text',s.practice),
jsonb_build_object('grading_mode','completion_only_reference','model_answer','تحتاج أصالة الإنتاج وترابطه وسلامة لغته إلى مراجعة المعلم.'),2,5,true,true FROM s WHERE NOT EXISTS(
SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=s.id AND a.content->>'origin'='DADYOOM_BH_G8_T1_WRITING_COMPLETION_LAST5_20261008' AND a.activity_type='writing');